import { beforeAll, describe, expect, it, vi } from 'vitest';
import { parseQuery, type RawParsedQuery } from '@/lib/search/query-parser';

// Spec: docs/slices/S4-nl-search.md, S4-back > LLM parser (test list 19–23).
// Every call injects `complete`, so no network is used. parseQuery caches by lowercased trimmed
// query, so each test uses its own query text.

beforeAll(() => {
  process.env.OPENAI_API_KEY = '';
});

function rawJson(overrides: Partial<RawParsedQuery> = {}): string {
  const value: RawParsedQuery = {
    skills: [],
    countries: [],
    minYears: null,
    maxYears: null,
    minSalary: null,
    maxSalary: null,
    seniority: null,
    keywords: [],
    searchText: '',
    ...overrides,
  };
  return JSON.stringify(value);
}

const CASE_4_FILTERS = {
  countries: ['Canada'],
  skills: ['React'],
  minYears: 5,
  maxYears: null,
  minSalary: null,
  maxSalary: 130000,
};

describe('parseQuery', () => {
  it("19. '' (or whitespace) → null", async () => {
    const complete = vi.fn(async () => rawJson());
    await expect(parseQuery('', { complete })).resolves.toBeNull();
    await expect(parseQuery('   ', { complete })).resolves.toBeNull();
  });

  it("20. a valid model response → source 'llm', filters as given plus seniority years", async () => {
    const complete = vi.fn(async () =>
      rawJson({
        skills: ['React'],
        countries: ['Canada'],
        maxSalary: 130000,
        seniority: 'senior',
        keywords: [],
        searchText: 'Senior React engineer',
      })
    );
    const r = await parseQuery('Senior React engineer in Canada under 130k', { complete });
    expect(complete).toHaveBeenCalledTimes(1);
    expect(r).not.toBeNull();
    expect(r!.source).toBe('llm');
    expect(r!.filters).toEqual(CASE_4_FILTERS);
    expect(r!.seniority).toBe('senior');
  });

  it("21. a complete that throws → source 'rules', same filters as case 4", async () => {
    // Differs from case 20's query only by a plural stopword, so it is a separate cache entry,
    // while the rules parser reads it exactly like case 4.
    const complete = vi.fn(async (): Promise<string> => {
      throw new Error('network down');
    });
    const r = await parseQuery('Senior React engineers in Canada under 130k', { complete });
    expect(r).not.toBeNull();
    expect(r!.source).toBe('rules');
    expect(r!.filters).toEqual(CASE_4_FILTERS);
  });

  it("22. a complete returning 'not json' → source 'rules'", async () => {
    const complete = vi.fn(async () => 'not json');
    const r = await parseQuery('python backend brazil bad json case', { complete });
    expect(r).not.toBeNull();
    expect(r!.source).toBe('rules');
  });

  it('23. the same query in different case or whitespace calls complete once', async () => {
    const complete = vi.fn(async () =>
      rawJson({ skills: ['Elixir'], keywords: ['cachetest'], searchText: 'Elixir cachetest' })
    );
    const first = await parseQuery('Elixir Cachetest Unique S4 Query', { complete });
    const second = await parseQuery('   elixir cachetest unique s4 query  ', { complete });
    expect(complete).toHaveBeenCalledTimes(1);
    expect(second).toEqual(first);
  });
});
import { describe, expect, it } from 'vitest';
import { parseQueryWithRules } from '@/lib/search/rules-parser';

// Spec: docs/slices/S4-nl-search.md, S4-back > Rule-based parser (test list 4–13).

describe('parseQueryWithRules', () => {
  it("4. 'Senior React engineer in Canada under 130k'", () => {
    const r = parseQueryWithRules('Senior React engineer in Canada under 130k');
    expect(r.source).toBe('rules');
    expect(r.filters).toEqual({
      countries: ['Canada'],
      skills: ['React'],
      minYears: 5,
      maxYears: null,
      minSalary: null,
      maxSalary: 130000,
    });
    expect(r.seniority).toBe('senior');
    expect(r.keywords).toEqual([]);
  });

  it("5. 'Rust developer with 5+ years experience in AI/ML'", () => {
    const r = parseQueryWithRules('Rust developer with 5+ years experience in AI/ML');
    expect(r.source).toBe('rules');
    // Domain skills rank, they don't filter: AI / Machine Learning move to keywords.
    expect(r.filters.skills).toEqual(['Rust']);
    expect(r.filters.minYears).toBe(5);
    expect(r.seniority).toBeNull();
    expect(r.keywords).toEqual(['ai', 'machine learning']);
  });

  it("6. 'python data engineer, max $8k/month, Brazil' (monthly ×12)", () => {
    const r = parseQueryWithRules('python data engineer, max $8k/month, Brazil');
    expect(r.source).toBe('rules');
    expect(r.filters.skills).toEqual(['Python']);
    expect(r.filters.countries).toEqual(['Brazil']);
    expect(r.filters.maxSalary).toBe(96000);
    expect(r.keywords).toContain('data');
  });

  it("7. 'backend between 60k and 90k'", () => {
    const r = parseQueryWithRules('backend between 60k and 90k');
    expect(r.source).toBe('rules');
    expect(r.filters.minSalary).toBe(60000);
    expect(r.filters.maxSalary).toBe(90000);
    expect(r.keywords).toEqual(['backend']);
  });

  it("8. 'java 3-6 years'", () => {
    const r = parseQueryWithRules('java 3-6 years');
    expect(r.source).toBe('rules');
    expect(r.filters.minYears).toBe(3);
    expect(r.filters.maxYears).toBe(6);
    expect(r.filters.skills).toEqual(['Java']);
  });

  it("9. 'junior frontend' → junior implies maxYears 3", () => {
    const r = parseQueryWithRules('junior frontend');
    expect(r.source).toBe('rules');
    expect(r.seniority).toBe('junior');
  it("11. 'fintech payments' → no filters, only keywords", () => {
    const r = parseQueryWithRules('fintech payments');
    expect(r.source).toBe('rules');
    expect(r.filters).toEqual({
      countries: [],
      skills: [],
      minYears: null,
      maxYears: null,
      minSalary: null,
      maxSalary: null,
    });
    expect(r.seniority).toBeNull();
    expect(r.keywords).toEqual(['fintech', 'payments']);
    expect(r.searchText).toBe('fintech payments');
  });

  it("12. 'under 5 years of go' → years, not salary", () => {
    const r = parseQueryWithRules('under 5 years of go');
    expect(r.source).toBe('rules');
    expect(r.filters.maxYears).toBe(5);
    expect(r.filters.maxSalary).toBeNull();
  });

  it("13. '100-130k react' → k on the second number applies to both", () => {
    const r = parseQueryWithRules('100-130k react');
    expect(r.source).toBe('rules');
    expect(r.filters.minSalary).toBe(100000);
    expect(r.filters.maxSalary).toBe(130000);
  });
});

